<template><div class="page"><el-card><template #header>电站详情</template><el-descriptions :column="2" border><el-descriptions-item label="电站ID">{{ id }}</el-descriptions-item><el-descriptions-item label="实时功率">{{ latest?.powerKw }} kW</el-descriptions-item><el-descriptions-item label="风速">{{ latest?.windSpeed }}</el-descriptions-item><el-descriptions-item label="辐照度">{{ latest?.irradiance }}</el-descriptions-item></el-descriptions></el-card><div class="panel"><BaseChart :option="option"/></div></div></template><script setup lang="ts">import { computed,onMounted,ref } from 'vue'; import { useRoute } from 'vue-router'; import BaseChart from '@/components/charts/BaseChart.vue'; import { realTimePower } from '@/api/power'; const id=Number(useRoute().params.id); const rows=ref<any[]>([]); const latest=computed(()=>rows.value[0]); onMounted(async()=>rows.value=(await realTimePower({stationId:id}) as any).data); const option=computed(()=>({xAxis:{type:'category',data:rows.value.map(r=>String(r.recordTime).slice(11,16)).reverse()},yAxis:{type:'value'},series:[{type:'line',smooth:true,data:rows.value.map(r=>r.powerKw).reverse()}]}))</script>
